//! Oracle tier: reads Goldmark artifacts regenerated by
//! `scripts/regen-fixtures.py` (see docs/FIXTURES.md).
#![cfg(feature = "oracle-fixtures")]
use d2_rs_text::markdown::{
    bytes::Bytes,
    inline::{InlineNode, merge_or_append_text_segment, merge_or_replace_text_segment},
    text::Segment,
};
use serde::Deserialize;
use serde_json::{Value, json};
#[derive(Deserialize)]
#[serde(rename_all = "PascalCase")]
struct Request {
    source: String,
    children: Vec<InlineNode>,
    action: String,
    index: usize,
    right: InlineNode,
    segment: Segment,
}
#[derive(Deserialize)]
struct Fixture {
    requests: Vec<Request>,
    results: Vec<Value>,
}
#[test]
fn pinned_goldmark_text_merge_boundaries() {
    let f: Fixture = serde_json::from_str(d2_rs_testdata::oracle_fixture!(
        "tests/fixtures/text-merge.json"
    ))
    .unwrap();
    assert!(!f.requests.is_empty());
    assert_eq!(f.requests.len(), f.results.len());
    for (i, (q, expected)) in f.requests.into_iter().zip(f.results).enumerate() {
        let source: Vec<_> = (0..q.source.len())
            .step_by(2)
            .map(|i| u8::from_str_radix(&q.source[i..i + 2], 16).unwrap())
            .collect();
        let mut children = q.children;
        let merged = match q.action.as_str() {
            "merge" => {
                let InlineNode::Text(t) = &mut children[q.index] else {
                    panic!("not text")
                };
                json!(t.merge(&q.right, &Bytes::new(&source)))
            }
            "append" => {
                merge_or_append_text_segment(&mut children, q.segment);
                Value::Null
            }
            "replace" => {
                merge_or_replace_text_segment(&mut children, q.index, q.segment);
                Value::Null
            }
            _ => panic!("unknown action"),
        };
        assert_eq!(
            json!({"merged":merged,"children":children}),
            expected,
            "case {i}"
        );
    }
}
